use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub assay_ref: String,
    pub inlet_vials: i64,
    pub outlet_vials: i64,
    pub reagent_cartridges: i64,
    pub assay_benches: i64,
    pub contamination_alert: bool,
    pub repeated_submission: bool,
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub assay_ref: String,
    pub sample_tally: i64,
    pub assay_effort: i64,
    pub bench_allowance: i64,
    pub examined_effort: i64,
    pub pending_assay: i64,
    pub assay_cycles: i64,
    pub assay_rating: i64,
    pub assay_phase: String,
}

pub fn score(inlet: i64, outlet: i64, reagents: i64, benches: i64, alert: bool) -> i64 {
    let effort = inlet * 11 + outlet * 7 + reagents * 9 + if alert { reagents * 4 } else { 0 };
    let allowance = benches * 52;
    let examined = effort.min(allowance);
    let pending = (effort - allowance).max(0);
    let cycles = (effort + 26) / 27;
    examined + pending * 4 + cycles * 8
}

pub fn calculate(v: &RequestInput) -> ResponseOutput {
    let sample_tally = v.inlet_vials + v.outlet_vials;
    let assay_effort = v.inlet_vials * 11 + v.outlet_vials * 7 + v.reagent_cartridges * 9
        + if v.contamination_alert { v.reagent_cartridges * 4 } else { 0 };
    let bench_allowance = v.assay_benches * 52;
    let examined_effort = assay_effort.min(bench_allowance);
    let pending_assay = (assay_effort - bench_allowance).max(0);
    let assay_cycles = (assay_effort + 26) / 27;
    ResponseOutput {
        assay_ref: v.assay_ref.clone(), sample_tally, assay_effort, bench_allowance,
        examined_effort, pending_assay, assay_cycles,
        assay_rating: score(v.inlet_vials, v.outlet_vials, v.reagent_cartridges, v.assay_benches, v.contamination_alert),
        assay_phase: if pending_assay == 0 { "dispatched" } else if v.contamination_alert { "contamination_queue" } else { "routine_queue" }.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_browser_score(a0: i64, a1: i64, a2: i64, a3: i64, a4: i32) -> i64 {
    score(a0, a1, a2, a3, a4 != 0)
}

